interface IModalExerciseProps {
  isHidden: boolean;
  exerciseType?: IExerciseType;
  settings: ISettings;
  initialFilter?: string;
  initialFilterTypes?: string[];
  isLoggedIn: boolean;
  shouldAddExternalLinks?: boolean;
  onSaveAsTemplate?: (name: string | undefined, label: string | undefined) => void;
  templateName?: string;
  label?: string;
  onLabelChange?: (label: string) => void;
  onChange: (value: IExerciseType | undefined, label: string | undefined, shouldClose: boolean) => void;
  onCreateOrUpdate: (
    shouldClose: boolean,
    name: string,
    targetMuscles: IMuscle[],
    synergistMuscles: IMuscle[],
    types: IExerciseKind[],
    smallImageUrl?: string,
    largeImageUrl?: string,
    videoUrl?: string,
    exercise?: ICustomExercise
  ) => void;
  customExerciseName?: string;
  onDelete: (id: string) => void;
}

export function ModalExercise(props: IModalExerciseProps): JSX.Element {
  const textInput = useRef<HTMLInputElement>(null);
  const [filter, setFilter] = useState<string>(props.initialFilter || "");
  const [isCustomExerciseDisplayed, setIsCustomExerciseDisplayed] = useState<boolean>(!!props.customExerciseName);
  const [editingExercise, setEditingExercise] = useState<ICustomExercise | undefined>(undefined);

  return (
    <Modal
      isHidden={props.isHidden}
      autofocusInputRef={textInput}
      shouldShowClose={true}
      onClose={() => props.onChange(undefined, undefined, true)}
    >
      <div style={{ maxWidth: "600px", minWidth: "260px" }}>
        {isCustomExerciseDisplayed ? (
          <CustomExerciseForm
            isLoggedIn={props.isLoggedIn}
            backLabel="Back to list"
            exercise={editingExercise}
            customExerciseName={props.customExerciseName}
            setIsCustomExerciseDisplayed={setIsCustomExerciseDisplayed}
            settings={props.settings}
            onCreateOrUpdate={props.onCreateOrUpdate}
          />
        ) : (
          <ExercisePickerContainer
            filter={filter}
            initialFilterTypes={props.initialFilterTypes}
            shouldAddExternalLinks={props.shouldAddExternalLinks}
            label={props.label}
            onLabelChange={props.onLabelChange}
            onSaveAsTemplate={props.onSaveAsTemplate}
            templateName={props.templateName}
            setFilter={setFilter}
            setIsCustomExerciseDisplayed={setIsCustomExerciseDisplayed}
            setEditingExercise={setEditingExercise}
            textInput={textInput}
            exerciseType={props.exerciseType}
            onChange={props.onChange}
            onDelete={props.onDelete}
            settings={props.settings}
          />
        )}
      </div>
    </Modal>
  );
}

type IExercisePickerContainerProps = Omit<IExercisesListProps, "isSubstitute">;

const ExercisePickerContainer = forwardRef((props: IExercisePickerContainerProps, _ref) => {
  const exerciseType = props.exerciseType;
  const onSaveAsTemplate = props.onSaveAsTemplate;
  const labelRef = useRef<HTMLInputElement>(null);

  return (
    <div>
      {props.onLabelChange && (
        <Input
          label="Label"
          ref={labelRef}
          defaultValue={props.label}
          changeType={"oninput"}
          inputSize="sm"
          pattern="^[^\/\{\}\(\)\t\n\r#\[\]]+$"
          patternMessage="Label cannot contain special characters: '/{}()#[]'"
          labelSize="xs"
          changeHandler={(e: IEither<string, Set<IValidationError>>) => {
            if (e.success && props.onLabelChange) {
              props.onLabelChange(e.data);
            }
          }}
        />
      )}
      {exerciseType === null ? (
        <ExercisesList isSubstitute={false} {...props} />
      ) : (
        <ScrollableTabs
          topPadding={props.onLabelChange ? "0.5rem" : "1.5rem"}
          defaultIndex={0}
          tabs={[
            {
              label: "Pick",
              children: () => <ExercisesList isSubstitute={false} labelRef={labelRef} {...props} />,
            },
            {
              label: "Substitute",
              children: () => <ExercisesList isSubstitute={true} labelRef={labelRef} {...props} />,
            },
            ...(onSaveAsTemplate
              ? [
                  {
                    label: "Template",
                    children: () => (
                      <ExerciseTemplate
                        templateName={props.templateName}
                        onSaveAsTemplate={onSaveAsTemplate}
                        labelRef={labelRef}
                      />
                    ),
                  },
                ]
              : []),
          ]}
        />
      )}
    </div>
  );
});

interface IExercisesListProps {
  settings: ISettings;
  filter: string;
  shouldAddExternalLinks?: boolean;
  templateName?: string;
  label?: string;
  labelRef?: RefObject<HTMLInputElement | null>;
  onSaveAsTemplate?: (name: string | undefined, label: string | undefined) => void;
  onLabelChange?: (label: string) => void;
  isSubstitute: boolean;
  initialFilterTypes?: string[];
  setFilter: (newFilter: string) => void;
  setEditingExercise: (exercise?: ICustomExercise) => void;
  setIsCustomExerciseDisplayed: (value: boolean) => void;
  exerciseType?: IExerciseType;
  onChange: (value: IExerciseType | undefined, label: string | undefined, shouldClose: boolean) => void;
  onDelete: (id: string) => void;
  textInput: RefObject<HTMLInputElement | null>;
}

const ExercisesList = forwardRef((props: IExercisesListProps, _ref): JSX.Element => {
  const { textInput, setFilter, filter } = props;

  let exercises = Exercise_allExpanded({});
  let customExercises = props.settings.exercises;
  const filterOptions = [
    ...equipments.map((e) => equipmentName(e)),
    ...exerciseKinds.map(StringUtils_capitalize),
    ...Muscle_getAvailableMuscleGroups(props.settings).map((mg) => Muscle_getMuscleGroupName(mg, props.settings)),
  ];
  const initialFilterOptions = (props.initialFilterTypes || []).filter((ft) => filterOptions.indexOf(ft) !== -1);
  const [filterTypes, setFilterTypes] = useState<string[]>(initialFilterOptions);
  if (filter) {
    exercises = Exercise_filterExercises(exercises, filter);
    customExercises = Exercise_filterCustomExercises(customExercises, filter);
  }
  if (filterTypes && filterTypes.length > 0) {
    exercises = Exercise_filterExercisesByType(exercises, filterTypes, props.settings);
    customExercises = Exercise_filterCustomExercisesByType(filterTypes, props.settings);
  }

  exercises = Exercise_sortExercises(exercises, props.isSubstitute, props.settings, filterTypes, props.exerciseType);
  const exercise = props.exerciseType ? Exercise_get(props.exerciseType, props.settings.exercises) : undefined;

  return (
    <form data-cy="modal-exercise" onSubmit={(e) => e.preventDefault()}>
      {props.isSubstitute && (
        <p className="text-xs italic">Similar exercises are sorted by the same muscles as the current one.</p>
      )}
      {exercise && (
        <div className="px-4 py-2 mb-2 bg-purple-100 rounded-2xl">
          <GroupHeader name="Current" />
          <ExerciseItem
            shouldAddExternalLinks={props.shouldAddExternalLinks}
            showMuscles={props.isSubstitute}
            settings={props.settings}
            exercise={exercise}
            equipment={exercise.equipment}
          />
        </div>
      )}
      <input
        ref={textInput}
        className="block w-full px-4 py-2 mb-2 text-base leading-normal border border-gray-300 rounded-lg appearance-none bg-background-default focus:outline-none focus:shadow-outline"
        type="text"
        value={filter}
        data-cy="exercise-filter-by-name"
        placeholder="Filter by name"
        onInput={() => {
          setFilter(textInput.current!.value.toLowerCase());
        }}
      />
      <Multiselect
        id="filtertypes"
        label=""
        data-cy="exercise-filter-by-type"
        placeholder="Filter by type"
        values={filterOptions}
        initialSelectedValues={new Set(initialFilterOptions)}
        onChange={(ft) => setFilterTypes(Array.from(ft))}
      />
      {!props.isSubstitute && (
        <>
          <GroupHeader name="Custom exercises" />
          {ObjectUtils_keys(customExercises)
            .filter((id) => !customExercises[id]?.isDeleted)
            .map((id) => {
              const e = customExercises[id]!;
              return (
                <section
                  key={id}
                  data-cy={`menu-item-${StringUtils_dashcase(e.name)}`}
                  className="w-full px-2 py-1 text-left border-b border-gray-200"
                  onClick={(event) => {
                    if (!HtmlUtils_classInParents(event.target as Element, "button")) {
                      const labelValue = props.labelRef?.current?.validationMessage
                        ? undefined
                        : props.labelRef?.current?.value;
                      props.onChange({ id: e.id }, labelValue, true);
                    }
                  }}
                >
                  <section className="flex items-center">
                    <div className="w-12 pr-2" style={{ minHeight: "2.5rem" }}>
                      <ExerciseImage settings={props.settings} className="w-full" exerciseType={e} size="small" />
                    </div>
                    <div className="flex-1 py-2 text-left">
                      <div>{e.name}</div>
                      <CustomMuscleGroupsView exercise={e} settings={props.settings} />
                    </div>
                    <div>
                      <button
                        className={`px-3 py-4 button nm-edit-custom-exercise-${StringUtils_dashcase(e.name)}`}
                        data-cy={`custom-exercise-edit-${StringUtils_dashcase(e.name)}`}
                        onClick={(event) => {
                          event.preventDefault();
                          props.setEditingExercise(e);
                          props.setIsCustomExerciseDisplayed(true);
                        }}
                      >
                        <IconEditSquare />
                      </button>
                      <button
                        className={`px-1 py-4 button nm-delete-custom-exercise-${StringUtils_dashcase(e.name)}`}
                        data-cy={`custom-exercise-delete-${StringUtils_dashcase(e.name)}`}
                        onClick={(event) => {
                          event.preventDefault();
                          if (confirm(`Are you sure you want to delete ${e.name}?`)) {
                            props.onDelete(e.id);
                          }
                        }}
                      >
                        <IconTrash />
                      </button>
                    </div>
                  </section>
                </section>
              );
            })}
          <div className="mb-4 text-sm">
            <LinkButton
              name="custom-exercise-create"
              data-cy="custom-exercise-create"
              onClick={(event) => {
                event.preventDefault();
                props.setEditingExercise(undefined);
                props.setIsCustomExerciseDisplayed(true);
              }}
            >
              Add Custom Exercise
            </LinkButton>
          </div>
        </>
      )}
      <GroupHeader name="Built-in exercises" />
      {exercises.map((e) => {
        return (
          <section
            key={Exercise_toKey(e)}
            data-cy={`menu-item-${StringUtils_dashcase(e.name)}${
              e.equipment ? `-${StringUtils_dashcase(e.equipment)}` : ""
            }`}
            className="w-full px-2 py-1 text-left border-b border-gray-200"
            onClick={() => {
              const labelValue = props.labelRef?.current?.validationMessage
                ? undefined
                : props.labelRef?.current?.value;
              props.onChange(e, labelValue, true);
            }}
          >
            <ExerciseItem
              shouldAddExternalLinks={props.shouldAddExternalLinks}
              showMuscles={props.isSubstitute}
              settings={props.settings}
              currentExerciseType={props.exerciseType}
              exercise={e}
              equipment={e.equipment}
            />
          </section>
        );
      })}
    </form>
  );
});

interface IExerciseItemProps {
  settings: ISettings;
  shouldAddExternalLinks?: boolean;
  currentExerciseType?: IExerciseType;
  exercise: IExercise;
  showMuscles: boolean;
  equipment?: IEquipment;
}

export function ExerciseItem(props: IExerciseItemProps): JSX.Element {
  const { exercise: e } = props;
  const exerciseType = { id: e.id, equipment: props.equipment || e.defaultEquipment };

  return (
    <section className="flex items-center">
      <div className="w-12 pr-2" style={{ minHeight: "2.5rem" }}>
        <ExerciseImage settings={props.settings} className="w-full" exerciseType={exerciseType} size="small" />
      </div>
      <div className="flex-1 py-2 text-sm text-left">
        <div>
          <span className="font-bold">{e.name}</span>,{" "}
          <span className="text-text-secondary">{equipmentName(exerciseType.equipment)}</span>
        </div>
        {props.showMuscles ? (
          <MuscleView currentExerciseType={props.currentExerciseType} exercise={e} settings={props.settings} />
        ) : (
          <MuscleGroupsView exercise={e} settings={props.settings} />
        )}
      </div>
      {props.shouldAddExternalLinks && (
        <div className="pl-1">
          <div className="flex items-center">
            <a className="p-2" href={Exercise_toExternalUrl(e)} target="_blank">
              <IconExternalLink />
            </a>
          </div>
        </div>
      )}
    </section>
  );
}

interface IEditCustomExerciseProps {
  settings: ISettings;
  backLabel: string;
  exercise?: ICustomExercise;
  isLoggedIn: boolean;
  setIsCustomExerciseDisplayed: (value: boolean) => void;
  onCreateOrUpdate: (
    shouldClose: boolean,
    name: string,
    targetMuscles: IMuscle[],
    synergistMuscles: IMuscle[],
    types: IExerciseKind[],
    smallImageUrl?: string,
    largeImageUrl?: string,
    videoUrl?: string,
    exercise?: ICustomExercise
  ) => void;
  customExerciseName?: string;
}

function CustomExerciseForm(props: IEditCustomExerciseProps): JSX.Element {
  const [notes, setNotes] = useState<string | undefined>(
    props.exercise ? Exercise_getNotes(props.exercise, props.settings) : undefined
  );
  const [state, dispatch] = useLensReducer(
    props.exercise ?? Exercise_createCustomExercise(props.customExerciseName ?? "", [], [], []),
    {},
    []
  );

  return (
    <form onSubmit={(e) => e.preventDefault()}>
      <div>
        <ExercisePickerCustomExerciseContent
          onGoBack={() => props.setIsCustomExerciseDisplayed(false)}
          settings={props.settings}
          notes={notes}
          setNotes={setNotes}
          hideNotes={true}
          hideDeleteButton={true}
          originalExercise={props.exercise}
          showMuscles={true}
          exercise={state}
          isLoggedIn={props.isLoggedIn}
          dispatch={dispatch}
          onClose={() => props.setIsCustomExerciseDisplayed(false)}
          onDelete={() => {}}
        />
      </div>
      <div className="py-4 flex">
        <div className="flex-1">
          <Button
            name="custom-exercise-cancel"
            kind="grayv2"
            data-cy="custom-exercise-cancel"
            onClick={(e) => {
              e.preventDefault();
              props.setIsCustomExerciseDisplayed(false);
            }}
          >
            {props.backLabel}
          </Button>
        </div>
        <div className="flex-1 text-right">
          <Button
            name="custom-exercise-create"
            kind="purple"
            data-cy="custom-exercise-create"
            onClick={(e) => {
              e.preventDefault();
              props.onCreateOrUpdate(
                true,
                state.name,
                state.meta.targetMuscles,
                state.meta.synergistMuscles,
                state.types || [],
                state.smallImageUrl,
                state.largeImageUrl,
                state.videoUrl,
                props.exercise
              );
              props.setIsCustomExerciseDisplayed(false);
            }}
          >
            {props.exercise != null ? "Update" : "Create"}
          </Button>
        </div>
      </div>
    </form>
  );
}

export function MuscleGroupsView(props: { exercise: IExercise; settings: ISettings }): JSX.Element {
  const { exercise, settings } = props;
  const targetMuscleGroups = Exercise_targetMusclesGroups(exercise, settings).map((m) =>
    Muscle_getMuscleGroupName(m, settings)
  );
  const synergistMuscleGroups = Exercise_synergistMusclesGroups(exercise, settings)
    .map((m) => Muscle_getMuscleGroupName(m, settings))
    .filter((m) => targetMuscleGroups.indexOf(m) === -1);

  const types = exercise.types.map((t) => StringUtils_capitalize(t));

  return (
    <div className="text-xs">
      {types.length > 0 && (
        <div>
          <span className="text-text-secondary">Type: </span>
          <span className="font-bold">{types.join(", ")}</span>
        </div>
      )}
      {targetMuscleGroups.length > 0 && (
        <div>
          <span className="text-text-secondary">Target: </span>
          <span className="font-bold">{targetMuscleGroups.join(", ")}</span>
        </div>
      )}
      {synergistMuscleGroups.length > 0 && (
        <div>
          <span className="text-text-secondary">Synergist: </span>
          <span className="font-bold">{synergistMuscleGroups.join(", ")}</span>
        </div>
      )}
    </div>
  );
}

function MuscleView(props: {
  currentExerciseType?: IExerciseType;
  exercise: IExercise;
  settings: ISettings;
}): JSX.Element {
  const { exercise, settings } = props;
  const tms = props.currentExerciseType ? Exercise_targetMuscles(props.currentExerciseType, settings) : [];
  const sms = props.currentExerciseType ? Exercise_synergistMuscles(props.currentExerciseType, settings) : [];
  const targetMuscles = Exercise_targetMuscles(exercise, settings);
  const synergistMuscles = Exercise_synergistMuscles(exercise, settings).filter((m) => targetMuscles.indexOf(m) === -1);

  const types = exercise.types.map((t) => StringUtils_capitalize(t));

  return (
    <div className="text-xs">
      {types.length > 0 && (
        <div>
          <span className="text-text-secondary">Type: </span>
          <span className="font-bold">{types.join(", ")}</span>
        </div>
      )}
      {targetMuscles.length > 0 && (
        <div>
          <span className="text-text-secondary">Target: </span>
          <span className="font-bold">
            {targetMuscles.map((m, i) => {
              return (
                <span key={m}>
                  <span
                    className={tms.length === 0 ? "" : tms.indexOf(m) !== -1 ? "text-text-success" : "text-text-error"}
                  >
                    {m}
                  </span>
                  {i !== targetMuscles.length - 1 ? ", " : ""}
                </span>
              );
            })}
          </span>
        </div>
      )}
      {synergistMuscles.length > 0 && (
        <div>
          <span className="text-text-secondary">Synergist: </span>
          <span className="font-bold">
            {synergistMuscles.map((m, i) => {
              return (
                <span key={m}>
                  <span
                    className={sms.length === 0 ? "" : sms.indexOf(m) !== -1 ? "text-text-success" : "text-text-error"}
                  >
                    {m}
                  </span>
                  {i !== synergistMuscles.length - 1 ? ", " : ""}
                </span>
              );
            })}
          </span>
        </div>
      )}
    </div>
  );
}

export function CustomMuscleGroupsView(props: { exercise: ICustomExercise; settings: ISettings }): JSX.Element {
  const { exercise } = props;
  const targetMuscleGroups = Array.from(
    new Set(
      CollectionUtils_flat(exercise.meta.targetMuscles.map((m) => Muscle_getScreenMusclesFromMuscle(m, props.settings)))
    )
  ).map((m) => StringUtils_capitalize(m));
  const synergistMuscleGroups = Array.from(
    new Set(
      CollectionUtils_flat(
        exercise.meta.synergistMuscles.map((m) => Muscle_getScreenMusclesFromMuscle(m, props.settings))
      )
    )
  )
    .map((m) => StringUtils_capitalize(m))
    .filter((m) => targetMuscleGroups.indexOf(m) === -1);
  const types = (exercise.types || []).map((t) => StringUtils_capitalize(t));

  return (
    <div className="text-xs">
      {types.length > 0 && (
        <div>
          <span className="text-text-secondary">Type: </span>
          <span className="font-bold">{types.join(", ")}</span>
        </div>
      )}
      {targetMuscleGroups.length > 0 && (
        <div>
          <span className="text-text-secondary">Target: </span>
          <span className="font-bold">{targetMuscleGroups.join(", ")}</span>{" "}
        </div>
      )}
      {synergistMuscleGroups.length > 0 && (
        <div>
          <span className="text-text-secondary">Synergist: </span>
          <span className="font-bold">{synergistMuscleGroups.join(", ")}</span>
        </div>
      )}
    </div>
  );
}

interface IExerciseTemplateProps {
  templateName?: string;
  labelRef?: RefObject<HTMLInputElement | null>;
  onSaveAsTemplate: (name: string | undefined, label: string | undefined) => void;
}

function ExerciseTemplate(props: IExerciseTemplateProps): JSX.Element {
  const [name, setName] = useState<string>(props.templateName ?? "");
  const [nameError, setNameError] = useState<string | undefined>(undefined);

  return (
    <form onSubmit={(e) => e.preventDefault()} className="mt-4">
      <LabelAndInput
        star={true}
        identifier="exercise-template-name"
        label="Template Name"
        errorMessage={nameError}
        value={name}
        placeholder="My Awesome Template"
        onInput={(e) => {
          const value = e.currentTarget.value?.trim() || "";
          setName(value);
          if (!value) {
            setNameError("Name cannot be empty");
          } else if (/[/{}()\t\n\r#\[\]]+/.test(value)) {
            setNameError("Name cannot contain special characters: '/{}()#[]'");
          } else {
            setNameError(undefined);
          }
        }}
      />
      <div className="my-2 text-sm">
        You can choose any name for the template, and it will be saved as <strong>"non-used"</strong> (i.e. as a
        template). You can reuse <strong>sets</strong>, <strong>warmup</strong>, <strong>update</strong> or{" "}
        <strong>progress</strong> from this template in your real exercises.
      </div>
      <div className="flex py-4">
        <div className="flex-1">
          <Button
            name="exercise-template-cancel"
            kind="grayv2"
            data-cy="exercise-template-cancel"
            onClick={() => props.onSaveAsTemplate && props.onSaveAsTemplate(undefined, undefined)}
          >
            Cancel
          </Button>
        </div>
        <div className="flex-1 text-right">
          <Button
            name="exercise-template-create"
            kind="purple"
            disabled={!!nameError}
            data-cy="exercise-template-create"
            onClick={() => {
              if (!name) {
                setNameError("Name cannot be empty");
              } else {
                setNameError(undefined);
                if (props.onSaveAsTemplate) {
                  const labelValue = props.labelRef?.current?.validationMessage
                    ? undefined
                    : props.labelRef?.current?.value;
                  props.onSaveAsTemplate(name, labelValue);
                }
              }
            }}
          >
            Save
          </Button>
        </div>
      </div>
    </form>
  );
}
